create or alter procedure [fusion].[GenerateEagleLineageData] @fusionId int, @includeEagleToBloomberg bit = 1 as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
declare @intersectTypeId int;
declare @bloombergMnemonicTypeId int = 301;
declare @eagleReportProfileTypeId int = 191; declare @eaglePortalQueryTypeId int = 192; declare @eagleDatamartFieldTypeId int = 193; declare @eagleDatamartModelTypeId int = 194; declare @eagleMessageStreamTypeId int = 196; declare @eagleReportRuleTypeId int = 197; declare @eagleFieldAttributeTypeId int = 201; declare @eagleInventoryOfFieldTypeId int = 205; declare @eagleFieldRuleTypeId int = 206; declare @eagleSourceRuleTypeId int = 208; declare @eagleSourceRuleItemTypeId int = 209; declare @eagleGroupingRuleTypeId int = 210; declare @eagleReferenceDataCenterStrategyTypeId int = 215; declare @eagleReferenceDataCenterValidationTypeId int = 216; declare @eagleReferenceDataCenterFieldGroupTypeId int = 218; declare @eagleReferenceDataCenterGoldCopyTypeId int = 217;
declare @fusionTypeId int; select @fusionTypeId = FusionTypeID from [dbo].[Fusion] where ID = @fusionId; if @fusionTypeId != 16 begin raiserror('ERROR - The eagle fusion lineage generation process may only be run for the Eagle DB Fusion Type', 16, -1); return; end
IF OBJECT_ID('tempdb..#maps') IS NOT NULL DROP TABLE #maps;
create table #maps ( ID int identity primary key, MapRuleItemID int, SourceFusionAttributeID int, SourceFusionAttributeTypeID int, SourceObject nvarchar(500), TargetFusionAttributeID int, TargetFusionAttributeTypeID int, TargetObject nvarchar(500) );
CREATE NONCLUSTERED INDEX [CIX_TempMaps] ON #maps ( SourceFusionAttributeID ASC, TargetFusionAttributeID ASC );
if ( @includeEagleToBloomberg = 1 ) begin
select @intersectTypeId = id from intersecttype where subjectid = @eagleInventoryOfFieldTypeId and [subject] = 'FusionAttributeType' and objectid = @bloombergMnemonicTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for bloomberg mnemonic/ eagle db column relations', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleMessageStreamTypeId and [subject] = 'FusionAttributeType' and objectid = @bloombergMnemonicTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for bloomberg mnemonic/ eagle message stream relations', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId);
set @intersectTypeId = null; end
select @intersectTypeId = id from intersecttype where subjectid = @eagleFieldAttributeTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleInventoryOfFieldTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ eagle db column relations', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId); set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleFieldRuleTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ eagle field rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId); set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleFieldAttributeTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ eagle field attribute', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId); set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleGroupingRuleTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ eagle grouping rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReportRuleTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldRuleTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field rule/ eagle report rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eaglePortalQueryTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldRuleTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field rule/ eagle portal query', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReferenceDataCenterValidationTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ rdc validation', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReferenceDataCenterStrategyTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ rdc data strategy', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReferenceDataCenterGoldCopyTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleReferenceDataCenterStrategyTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle rdc gold copy / rdc data strategy', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleDatamartFieldTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleFieldAttributeTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle field attribute/ datamart field', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].FusionAttribute FA_s inner join [dbo].FusionAttribute FA_t on (FA_t.ParentID = FA_s.ID and FA_t.FusionAttributeTypeId = @eagleDatamartFieldTypeId) where FA_s.FusionAttributeTypeId = @eagleDatamartModelTypeId and FA_s.FusionID = @fusionId
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReportProfileTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleReportRuleTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle report profile/ report rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleReportRuleTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleSourceRuleTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle report rule / source rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
