insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eagleDatamartModelTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleSourceRuleTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle datamart model / source rule', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
select @intersectTypeId = id from intersecttype where subjectid = @eaglePortalQueryTypeId and [subject] = 'FusionAttributeType' and objectid = @eagleReportProfileTypeId and [object] = 'FusionAttributeType'; if @intersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for eagle portal query/ report profile', 16, -1); return; end
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].[intersect] I inner join [dbo].FusionAttribute FA_t on (FA_t.ID = I.subjectID and I.intersecttypeid = @intersectTypeId and FA_t.FusionID = @fusionId) inner join [dbo].FusionAttribute FA_s on (FA_s.ID = I.objectID and I.intersecttypeid = @intersectTypeId and FA_s.FusionID = @fusionId);
set @intersectTypeId = null;
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject) select FA_s.ID as SourceFusionAttributeID, FA_s.FusionAttributeTypeID as SourceFusionAttributeTypeID, FA_s.Name as SourceObject, FA_t.ID as TargetFusionAttributeID, FA_t.FusionAttributeTypeID as TargetFusionAttributeTypeID, FA_t.Name as TargetObject from [dbo].FusionAttribute FA_t inner join [dbo].FusionAttribute FA_s on (FA_s.ParentID = FA_t.ID and FA_s.FusionAttributeTypeId = @eagleSourceRuleItemTypeId) where FA_t.FusionAttributeTypeId = @eagleSourceRuleTypeId and FA_t.FusionID = @fusionId;
update T set T.mapruleitemid = S.id from #maps T inner join [dbo].[mapruleitem] S on (S.[owner] = 'EAGLE LINEAGE' and S.SourceFusionAttributeID = T.SourceFusionAttributeID and S.TargetFusionAttributeID = T.TargetFusionAttributeID);
MERGE INTO mapruleitem mri USING ( select SourceFusionAttributeID, TargetFusionAttributeID from #maps where mapruleitemid is null ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceFusionAttributeID, TargetFusionAttributeID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.SourceFusionAttributeID, S.TargetFusionAttributeID, 0, getutcdate(), 0, getutcdate(), 'EAGLE LINEAGE');
delete from mapruleitem where [owner] = 'EAGLE LINEAGE' and id not in(select m.mapruleitemid from #maps m); end
